export const LIVE_MANIFEST = freezeData(JSON.parse(GENERATED_MANIFEST_JSON) as LiveManifest);
export const LIVE_MANIFEST_DIGEST = LIVE_MANIFEST.digest;

function freezeData<Value>(value: Value): Value {
  if (value && typeof value === 'object') {
    Object.freeze(value);
    for (const child of Object.values(value as Record<string, unknown>)) freezeData(child);
  }
  return value;
}

export interface TargetSuitePolicy {
  readonly targetAlias: PhaseOneTargetAlias;
  readonly allowedSuites: readonly ['case', 'smoke'];
  readonly allowedVariants: readonly string[];
}

export type SuitePolicyErrorCode =
  | 'INVALID_TARGET_POLICY'
  | 'SUITE_NOT_ALLOWED'
  | 'CASE_SELECTION_REQUIRED'
  | 'VARIANT_NOT_ALLOWED'
  | 'SMOKE_INVENTORY_MISMATCH';

export class SuitePolicyError extends Error {
  readonly code: SuitePolicyErrorCode;

  constructor(code: SuitePolicyErrorCode) {
    super(code);
    this.name = 'SuitePolicyError';
    this.code = code;
  }
}

export function validateTargetSuitePolicy(input: unknown): TargetSuitePolicy {
  if (!isRecord(input)
    || !hasOnlyKeys(input, ['targetAlias', 'allowedSuites', 'allowedVariants'])
    || !(PHASE_ONE_TARGET_ALIASES as readonly unknown[]).includes(input.targetAlias)
    || !exactInventory(input.allowedSuites, ['case', 'smoke'])) {
    throw new SuitePolicyError('INVALID_TARGET_POLICY');
  }
  const allowedVariants = input.allowedVariants;
  if (!Array.isArray(allowedVariants)
    || allowedVariants.length === 0
    || new Set(allowedVariants).size !== allowedVariants.length
    || allowedVariants.some((variantId) => typeof variantId !== 'string'
      || !LIVE_MANIFEST.requiredVariants.case.includes(variantId))
    || PHASE_ONE_SMOKE_VARIANTS.some((variantId) => !allowedVariants.includes(variantId))) {
    throw new SuitePolicyError('INVALID_TARGET_POLICY');
  }
  return Object.freeze({
    targetAlias: input.targetAlias as PhaseOneTargetAlias,
    allowedSuites: Object.freeze(['case', 'smoke']) as readonly ['case', 'smoke'],
    allowedVariants: Object.freeze([...(allowedVariants as string[])]),
  });
}

export function resolveTargetSuiteVariants(
  policyInput: TargetSuitePolicy,
  suite: Suite,
  selectedVariantIds?: readonly string[],
): string[] {
  const policy = validateTargetSuitePolicy(policyInput);
  if (suite === 'deep' || !policy.allowedSuites.includes(suite as 'case' | 'smoke')) {
    throw new SuitePolicyError('SUITE_NOT_ALLOWED');
  }
  if (suite === 'smoke') {
    if (selectedVariantIds !== undefined
      && !exactInventory(selectedVariantIds, PHASE_ONE_SMOKE_VARIANTS)) {
      throw new SuitePolicyError('SMOKE_INVENTORY_MISMATCH');
    }
    return [...PHASE_ONE_SMOKE_VARIANTS];
  }
  if (selectedVariantIds === undefined || selectedVariantIds.length === 0) {
    throw new SuitePolicyError('CASE_SELECTION_REQUIRED');
  }
  if (new Set(selectedVariantIds).size !== selectedVariantIds.length
    || selectedVariantIds.some((variantId) => !policy.allowedVariants.includes(variantId))) {
    throw new SuitePolicyError('VARIANT_NOT_ALLOWED');
  }
  return [...selectedVariantIds];
}

function exactInventory(input: unknown, expected: readonly string[]): boolean {
  if (!Array.isArray(input) || input.some((value) => typeof value !== 'string')) return false;
  const actual = [...input].sort();
  const wanted = [...expected].sort();
  return actual.length === wanted.length
    && actual.every((value, index) => value === wanted[index]);
}

function isRecord(input: unknown): input is Record<string, unknown> {
  return input !== null && typeof input === 'object' && !Array.isArray(input);
}

function hasOnlyKeys(input: object, allowed: readonly string[]): boolean {
  const accepted = new Set(allowed);
  return Object.keys(input).every((key) => accepted.has(key));
}
